import 'package:flutter/services.dart';
import 'package:csv/csv.dart';
import 'package:ledger_zero/services/export/csv_sanitizer.dart';
import 'package:ledger_zero/services/export/export_file_service.dart';
import 'package:pdf/pdf.dart' deferred as pdf_lib;
import 'package:pdf/widgets.dart' deferred as pw;

/// Localised texts of an exported PDF report (the service has no
/// BuildContext; the screen passes them in the app language).
class ReportPdfLabels {
  /// Header line next to the title, e.g. "Created on 16.10.2026".
  final String createdOn;

  /// Footer text, e.g. "Generated by LedgerZero".
  final String footer;

  /// Footer page counter, e.g. "Page 1 of 3".
  final String Function(int page, int pages) pageOf;

  /// Text passed to the share sheet.
  final String shareText;

  const ReportPdfLabels({
    required this.createdOn,
    required this.footer,
    required this.pageOf,
    required this.shareText,
  });
}

class ReportExportService {
  final ExportFileService _files;

  ReportExportService({ExportFileService? files})
    : _files = files ?? ExportFileService();

  /// Font with full Latin coverage: the PDF standard fonts cannot draw
  /// characters outside Latin-1 such as "€", "„“" or "–".
  static const _regularFont = 'assets/fonts/Roboto-Regular.ttf';
  static const _boldFont = 'assets/fonts/Roboto-Bold.ttf';

  /// Shares [rows] as CSV. Text cells are neutralised against formula
  /// injection; wrap amounts and dates in [CsvLiteral] to keep them as-is.
  Future<void> shareCsv(
    List<List<dynamic>> rows,
    String filename, {
    String? shareText,
  }) async {
    final csv = const ListToCsvConverter().convert(CsvSanitizer.rows(rows));
    final file = await _files.writeString('$filename.csv', csv);
    await _files.shareAndDelete(file, text: shareText);
  }

  /// Generates a PDF report with a title, date, and a table of data.
  /// [title]: The title of the report.
  /// [headers]: The column headers for the table.
  /// [data]: The rows of data for the table (already formatted).
  /// [filename]: The output filename (without extension).
  /// [labels]: The localised header/footer texts.
  Future<void> generateAndSharePdf({
    required String title,
    required List<String> headers,
    required List<List<String>> data,
    required String filename,
    required ReportPdfLabels labels,
  }) async {
    await pdf_lib.loadLibrary();
    await pw.loadLibrary();

    final theme = pw.ThemeData.withFont(
      base: pw.Font.ttf(await rootBundle.load(_regularFont)),
      bold: pw.Font.ttf(await rootBundle.load(_boldFont)),
    );
    final pdf = pw.Document(theme: theme);

    pdf.addPage(
      pw.MultiPage(
        pageFormat: pdf_lib.PdfPageFormat.a4,
        header: (context) {
          return pw.Header(
            level: 0,
            child: pw.Row(
              mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
              children: [
                pw.Expanded(
                  child: pw.Text(
                    title,
                    style: pw.TextStyle(
                      fontSize: 24,
                      fontWeight: pw.FontWeight.bold,
                    ),
                  ),
                ),
                pw.Text(labels.createdOn),
              ],
            ),
          );
        },
        footer: (context) {
          return pw.Row(
            mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
            children: [
              pw.Text(labels.footer),
              pw.Text(labels.pageOf(context.pageNumber, context.pagesCount)),
            ],
          );
        },
        build: (context) {
          return [
            pw.SizedBox(height: 20),
            pw.TableHelper.fromTextArray(
              headers: headers,
              data: data,
              border: null,
              headerStyle: pw.TextStyle(fontWeight: pw.FontWeight.bold),
              headerDecoration: pw.BoxDecoration(
                color: pdf_lib.PdfColors.grey300,
              ),
              cellHeight: 30,
              cellAlignments: {
                for (var i = 0; i < headers.length; i++)
                  i: pw.Alignment.centerLeft,
              },
            ),
          ];
        },
      ),
    );

    final file = await _files.writeBytes('$filename.pdf', await pdf.save());
    await _files.shareAndDelete(file, text: labels.shareText);
  }

  Future<void> shareImage(
    Uint8List imageBytes,
    String filename, {
    String? shareText,
  }) async {
    final file = await _files.writeBytes('$filename.png', imageBytes);
    await _files.shareAndDelete(file, text: shareText);
  }
}
